const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alvordBasin = ee.Geometry.Rectangle([-118.65, 42.35, -118.35, 42.65]); // Alvord Desert basin
  const targetDate = '2025-06-29';
  const startDate = ee.Date(targetDate).advance(-1, 'day');
  const endDate = ee.Date(targetDate).advance(1, 'day');

  // 2. Data Acquisition - Try Sentinel-2 first
  let s2Col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(alvordBasin)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const s2Size = s2Col.size().getInfo();
  console.log(`Sentinel-2 images (${targetDate} ±1 day): ${s2Size}`);

  // Try Landsat 9 if Sentinel-2 has no images
  let image;
  let collectionName = '';

  if (s2Size > 0) {
    image = s2Col.first();
    collectionName = 'Sentinel-2';
  } else {
    // Try Landsat 9
    const ls9Col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(alvordBasin)
      .filterDate(startDate, endDate);

    const ls9Size = ls9Col.size().getInfo();
    console.log(`Landsat 9 images (${targetDate} ±1 day): ${ls9Size}`);

    if (ls9Size > 0) {
      image = ls9Col.first();
      collectionName = 'Landsat 9';
    } else {
      console.log('No Sentinel-2 or Landsat 9 images found.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  console.log(`Using ${collectionName} image from: ${image.date().format('YYYY-MM-dd').getInfo()}`);

  // 3. Processing - Compute NDWI for water detection
  if (collectionName === 'Sentinel-2') {
    // Sentinel-2: Green (B3) and NIR (B8)
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    image = image.addBands(ndwi);
  } else {
    // Landsat 9: Green (SR_B3) and NIR (SR_B5)
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    image = image.addBands(ndwi);
  }

  // Create water mask (NDWI > 0.2 typically indicates water)
  const waterMask = image.select('NDWI').gt(0.2);

  // 4. Count valid pixels
  const countResult = waterMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alvordBasin,
    scale: 1000,
    maxPixels: 1e9,
    bestEffort: true
  });

  const waterPixels = countResult.get('NDWI').getInfo();
  console.log(`Water pixels (NDWI > 0.2): ${waterPixels}`);

  // 5. Validation & Final Answer
  if (waterPixels === null || waterPixels === undefined) {
    console.log('<answer>C3</answer>');
  } else if (waterPixels > 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
